
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_mpw1kcis_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_mpw1kcis", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.724708570372634e+00, -3.654788035977307e+00, -3.556868581096270e+00, -3.421343122104672e+00, -3.236918026751152e+00, -2.991974913679978e+00, -2.677766104919391e+00, -2.294110334300160e+00, -1.856757078026473e+00, -1.399660747948310e+00, -9.551966018836682e-01, -6.455931743983855e-01, -5.549894664041732e-01, -4.549526112336386e-01, -3.327898715316585e-01, -2.164255303393789e-01, -1.248909501277306e-01, -4.207563213677908e-02, -1.075503809377177e-03, -2.690066493702344e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


